"""P7 gate (spec §10): artefacts are generated by scripts, not hand-written; audit holds."""
from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest

from chakravyuh.audit.ledger import read, verify
from chakravyuh.audit.trace import llm_trace_payload, load_prompt, store_prompt
from chakravyuh.schemas import sha256_text
from chakravyuh.sim.runner import run
from chakravyuh.y3172 import REGISTRY, Y3172Node, render_map

ROOT = Path(__file__).resolve().parents[1]


def _script(name: str, *args: str):
    return subprocess.run([sys.executable, str(ROOT / "app" / "scripts" / name), *args],
                          cwd=ROOT, capture_output=True, text=True, timeout=600)


def test_prompt_is_stored_by_hash_and_recoverable(tmp_path):
    prompt = "You are the competent authority. Decide."
    sha = store_prompt(prompt, tmp_path)
    assert sha == sha256_text(prompt)
    assert load_prompt(sha, tmp_path) == prompt
    assert load_prompt("0" * 64, tmp_path) is None


def test_llm_trace_payload_carries_everything_the_rubric_asks_for(tmp_path):
    payload = llm_trace_payload(model="ollama/qwen2.5:14b", prompt="p", raw_output="{}",
                               parsed={"action_type": "NOOP"}, latency_s=0.5,
                               tokens={"prompt": 10, "completion": 2},
                               retrieved_chunk_ids=["IN.TA2023.s20.2#0"], cache_status="hit",
                               role="tsp_network", trace_dir=tmp_path)
    for key in ("model", "prompt_sha256", "retrieved_chunk_ids", "raw_output", "parsed",
                "latency_s", "tokens", "cache_status", "role"):
        assert key in payload
    assert load_prompt(payload["prompt_sha256"], tmp_path) == "p"


def test_ledger_contains_every_required_entry_kind(scenario, india_pack, tmp_path):
    r = run(scenario, india_pack, seed=0, ledger_path=tmp_path / "l.jsonl")
    kinds = {e.kind for e in read(r.ledger_path)}
    for required in ("EVENT", "DELIVERY", "PROPOSAL", "VERDICT", "EFFECT", "PROPERTY"):
        assert required in kinds, required


def test_every_verdict_records_its_mode_and_explanation(scenario, india_pack, tmp_path):
    r = run(scenario, india_pack, seed=0, ledger_path=tmp_path / "l.jsonl")
    verdicts = [e for e in read(r.ledger_path) if e.kind == "VERDICT"]
    assert verdicts
    for e in verdicts:
        assert e.payload["mode"] in ("advisory", "blocking")
        assert e.payload["explanation"]
        assert e.payload["decision"] in ("ALLOW", "BLOCK", "NEEDS_HUMAN")


def test_run_header_and_footer_frame_the_ledger(scenario, india_pack, tmp_path):
    r = run(scenario, india_pack, seed=0, ledger_path=tmp_path / "l.jsonl")
    entries = list(read(r.ledger_path))
    assert entries[0].payload.get("kind") == "RUN_HEADER"
    assert entries[0].payload["pack_id"] == india_pack.pack_id
    footer = [e for e in entries if e.payload.get("kind") == "RUN_FOOTER"]
    assert footer and "latency_by_role" in footer[-1].payload


def test_y3172_registry_covers_every_node():
    import chakravyuh.kb.ingest  # noqa: F401
    import chakravyuh.policy.engine  # noqa: F401
    import chakravyuh.sim.game_master  # noqa: F401
    for node in Y3172Node:
        assert REGISTRY[node.value], f"no entry point registered for node {node.value}"


def test_y3172_map_is_generated_from_the_code():
    text = render_map()
    assert "generated by app/scripts/gen_y3172_map.py" in text
    assert "chakravyuh.policy.engine" in text
    assert "`P`" in text and "`SINK`" in text


