@pytest.mark.slow
def test_eval_adviser_script_reports_mechanical_criteria():
    res = _script("eval_adviser.py")
    assert res.returncode == 0, res.stderr
    data = json.loads((ROOT / "outputs/adviser_eval.json").read_text(encoding="utf-8"))
    n = data["summary"]["cases"]
    assert n >= 20, "the rubric calls for at least 20 mid-scenario questions"
    assert data["summary"]["c4_no_invented_clause"] == n, \
        "the citation gate must hold on every case"
    assert data["summary"]["human_checked"] == 0
    assert all(r["human_check"] == "" for r in data["rows"])


@pytest.mark.slow
def test_verify_ledger_script_detects_tampering(tmp_path, scenario, india_pack):
    r = run(scenario, india_pack, seed=0, ledger_path=tmp_path / "l.jsonl")
    ok = _script("verify_ledger.py", str(r.ledger_path))
    assert ok.returncode == 0, ok.stdout

    lines = Path(r.ledger_path).read_text().splitlines()
    entry = json.loads(lines[3])
    entry["payload"]["tampered"] = True
    lines[3] = json.dumps(entry, sort_keys=True)
    Path(r.ledger_path).write_text("\n".join(lines) + "\n")

    bad = _script("verify_ledger.py", str(r.ledger_path))
    assert bad.returncode == 1
    assert "FAIL" in bad.stdout
    assert not verify(r.ledger_path)[0]


@pytest.mark.slow
def test_check_sources_script_runs_offline_from_saved_results():
    """The URL check must be reportable without a network, so CI and demos are not flaky."""
    saved = ROOT / "outputs/source_check.json"
    if not saved.exists():
        pytest.skip("run app/scripts/check_sources.py once with network to seed outputs/source_check.json")
    res = _script("check_sources.py", "--offline")
    assert res.returncode == 0, res.stderr
    body = (ROOT / "docs/source_check.md").read_text(encoding="utf-8")
    assert "what it does not" in body.lower()
    assert "recalled rather than copied" in body


@pytest.mark.slow
def test_dead_urls_are_reported_against_the_records_that_cite_them():
    saved = ROOT / "outputs/source_check.json"
    if not saved.exists():
        pytest.skip("run app/scripts/check_sources.py once with network")
    data = json.loads(saved.read_text(encoding="utf-8"))
    dead_states = {"dead", "unreachable"}
    dead_urls = {u for u, v in data["per_url"].items() if v["state"] in dead_states}
    dead_recs = [cid for state, ids in data["records_by_state"].items()
                 if state in dead_states for cid in ids]
    if dead_urls:
        assert dead_recs, "dead URLs found but no clause records attributed to them"
        body = (ROOT / "docs/source_check.md").read_text(encoding="utf-8")
        for cid in dead_recs:
            assert cid in body, f"{cid} cites a dead URL but is not named in the report"
